moving_probe_driver:
import fs from 'node:fs'
import {spawn,execFileSync} from 'node:child_process'
import mineflayer from '/home/user/workspace/repo/body/node_modules/mineflayer/index.js'
const [dir,binary,root]=process.argv.slice(2)
fs.mkdirSync(dir,{recursive:true})
const log=v=>fs.appendFileSync(dir+'/transcript.jsonl',JSON.stringify({ts:Date.now(),...v})+'\n')
const sleep=ms=>new Promise(r=>setTimeout(r,ms))
const state=async()=>await(await fetch('http://127.0.0.1:7787/state')).json()
const player=mineflayer.createBot({host:'127.0.0.1',port:25565,username:'Alex',auth:'offline',version:'26.1'})
let replies=0
player.on('chat',(username,message)=>{log({username,message});if(username==='Clyde'){replies++;state().then(reply_state=>log({reply_state}))}})
await new Promise(r=>player.once('spawn',r))
await until(async()=>!!(await state()).bot,30000)
log({setup:execFileSync('/tmp/slice11/rcon',['tp Clyde 0.5 80 0.5','tp Alex 2.5 80 2.5','clear Clyde','gamemode creative Clyde','gamemode survival Clyde','effect give Clyde instant_health 1 10'],{encoding:'utf8'})})
fs.writeFileSync(dir+'/planner.md',fs.readFileSync(root+'/prompts/planner.md','utf8')+'\nIsolated attended session: on initial idle, wait for Alex. Do not start unrelated autonomous curriculum.\n')
const out=fs.openSync(dir+'/serve.log','a')
const proc=spawn(binary,['serve','--body','http://127.0.0.1:7787','--rcon','127.0.0.1:25575','--memory',dir+'/episodes.db','--semantic-dir',dir+'/semantic','--candidates-dir',dir+'/candidates','--planner-prompt',dir+'/planner.md','--judge','jev','--judge-log',dir+'/judge.jsonl','--max-steps','40','--max-time','300s'],{cwd:root,stdio:['ignore',out,out]})
let cursor=0,busy=false
const timer=setInterval(async()=>{if(busy)return;busy=true;try{const p=await(await fetch('http://127.0.0.1:7787/events?since='+cursor)).json();for(const event of p.events||[])log({event});cursor=p.latestSeq??cursor}finally{busy=false}},500)
async function until(f,ms=120000){const end=Date.now()+ms;while(!await f()){if(Date.now()>end)throw Error('probe deadline');await sleep(200)}}
function say(message){log({sent:message});player.chat('Clyde, '+message)}
try{
await sleep(3000)
say('Walk safely to 85 80 0, stop within two blocks, then wait for me. Do not dig or build.')
await until(async()=>{const c=await state();return c.action && c.bot.position.x>3 && c.bot.position.x<60})
log({question_start_state:await state()})
const before=replies
say('What are you working on? Answer without changing the work; keep walking.')
await until(()=>replies>before)
log({question_answer_state:await state()})
say('Change of plan: replace that destination. Walk back to 12 80 0, within two blocks, then wait. Do not resume the old destination.')
await until(async()=>{const c=await state();return !c.action && Math.hypot(c.bot.position.x-12,c.bot.position.y-80,c.bot.position.z)<2},90000)
await sleep(10000)
log({final_state:await state(),server:execFileSync('/tmp/slice11/rcon',['data get entity Clyde Pos'],{encoding:'utf8'})})
}catch(error){log({probe_error:String(error)})}finally{
if(proc.exitCode===null){proc.kill('SIGTERM');await new Promise(r=>proc.once('exit',r))}
clearInterval(timer);player.quit()
}

