package main
import("context";"fmt";"os";"github.com/lox/clyde/harness/rcon";"github.com/lox/clyde/harness/gym")
func main(){ c,e:=rcon.Dial(context.Background(),"127.0.0.1:25575",gym.RCONPassword());if e!=nil{panic(e)};defer c.Close();for _,s:=range os.Args[1:]{r,e:=c.Exec(s);fmt.Println(r,e)} }

